script:
(function () {
  'use strict';
  // ---- VA funding fee schedule (in effect for 2026) -------------------------------------------
  // Source: VA, "VA funding fee and loan closing costs" (va.gov, rates for loans closed on or after
  // April 7, 2023); VA Circular 26-23-06 and Change 2 (schedule runs until June 9, 2034); 38 U.S.C.
  // 3729(b)(2). Same rates for Veterans, active-duty service members and National Guard/Reserve.
  //   Purchase or construction, as a % of the loan amount:
  //     Down payment     First use   After first use
  //     Less than 5%     2.15%       3.3%
  //     5% or more       1.5%        1.5%
  //     10% or more      1.25%       1.25%
  //   Down payment % = down payment / purchase price, not rounded (Circular 26-23-06, para. 4).
  //   Exempt (38 U.S.C. 3729(c), va.gov): receiving VA compensation for a service-connected
  //   disability; eligible for that compensation but receiving retirement or active-duty pay
  //   instead; surviving spouses receiving Dependency and Indemnity Compensation (DIC); service
  //   members with a proposed or memorandum rating from a pre-discharge claim; active-duty service
  //   members who give evidence of a Purple Heart before closing.
  var FEE_YEAR_LABEL = '2026';
  var FEE_TABLE = [ // [minimum down %, first use, after first use]
    [10, 0.0125, 0.0125],
    [5, 0.015, 0.015],
    [0, 0.0215, 0.033]
  ];
  function fundingFeeRate(downPct, subsequent, exempt) {
    if (exempt) return 0;
    for (var k = 0; k < FEE_TABLE.length; k++) {
      if (downPct >= FEE_TABLE[k][0] - 1e-9) return subsequent ? FEE_TABLE[k][2] : FEE_TABLE[k][1];
    }
    return subsequent ? 0.033 : 0.0215;
  }
  // ---------------------------------------------------------------------------------------------
  // Fee = rate * base loan (price - down payment), rounded to the cent; financed -> added to the loan.
  // Payment: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = years * 12 (M = L / n at 0%).
  // VA loans have no monthly mortgage insurance, so none is added.
  // Verified in Node (scratchpad tests/w3re): $500,000, 0% down, first use, financed -> 2.15% fee
  //   $10,750, loan $510,750, P&I at 7.373% for 30 yrs $3,526.93 and total interest $758,943.77 (both
  //   match a published VA calculator's defaults to the cent); VA Circular 26-23-06's worked example
  //   ($300,000 price, $18,000 down = 6%) gives a fee on the $282,000 loan, at today's 1.5% = $4,230;
  //   bands switch exactly at 5.00% and 10.00% down; subsequent use < 5% = 3.3%; exempt = $0; fee paid
  //   in cash leaves the loan at the base amount; 0% rate -> L / n; no NaN/Infinity on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function round2(v) { return Math.round(v * 100 + 1e-9) / 100; }

  function payment(loan, annualPct, months) {
    if (loan <= 0 || months <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return loan / months;
    return loan * i / (1 - Math.pow(1 + i, -months));
  }

  function schedule(loan, annualPct, months) {
    var pay = payment(loan, annualPct, months), bal = loan, rows = [], totalInterest = 0, p = 0, intr = 0;
    for (var m = 1; m <= months; m++) {
      var interest = bal * annualPct / 1200;
      var principal = m === months ? bal : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest; p += principal; intr += interest;
      if (m % 12 === 0 || m === months) {
        rows.push({ year: Math.ceil(m / 12), principal: p, interest: intr, balance: bal });
        p = 0; intr = 0;
      }
    }
    return { pay: pay, rows: rows, totalInterest: totalInterest };
  }

  function clearResults() {
    ['vaMonthly', 'vaLoan', 'vaFee', 'vaFeeRate', 'vaPI', 'vaTaxMo', 'vaInsMo', 'vaHoaMo', 'vaBase', 'vaCashClose',
     'vaTotalInterest', 'vaTotalPaid'].forEach(function (id) { setText(id, '–'); });
    setText('vaFeeNote', '');
    setText('vaDownHint', 'VA loans allow 0% down if you have full entitlement.');
    el('vaSchedule').innerHTML = '';
  }

  function update() {
    var price = read('vaPrice'), down = read('vaDown', true), downUnit = el('vaDownUnit').value, rate = read('vaRate'),
        years = parseInt(el('vaTerm').value, 10), subsequent = el('vaUse').value === 'subsequent',
        exempt = el('vaExempt').checked, financed = el('vaFinance').checked,
        tax = read('vaTax', true), taxUnit = el('vaTaxUnit').value, ins = read('vaIns', true), hoa = read('vaHoa', true);
    var downAmt = downUnit === 'percent' ? price * down / 100 : down;
    var msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a home price greater than $0.';
    else if (isNaN(down) || down < 0 || !(downAmt < price)) msg = 'Enter a down payment of 0 or more that is less than the home price.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(years) || years < 1) msg = 'Choose a loan term.';
    else if ([tax, ins, hoa].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Taxes, insurance and HOA dues cannot be negative.';
    else if (taxUnit === 'percent' && tax > 20) msg = 'Enter a property tax rate of 20% or less.';
    var error = el('vaError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var downPct = downAmt / price * 100;
    var base = price - downAmt;
    var feeRate = fundingFeeRate(downPct, subsequent, exempt);
    var fee = round2(base * feeRate);
    var loan = financed ? base + fee : base;
    var months = years * 12;
    var r = schedule(loan, rate, months);
    var annualTax = taxUnit === 'percent' ? price * tax / 100 : tax;

    setText('vaDownHint', (downUnit === 'percent' ? '= ' + money.format(downAmt) : '= ' + downPct.toFixed(2) + '% of the price') +
      '. VA loans allow 0% down if you have full entitlement.');
    setText('vaMonthly', money.format(r.pay + annualTax / 12 + ins / 12 + hoa));
    setText('vaLoan', money.format(loan));
    setText('vaFee', money.format(fee));
    setText('vaFeeRate', (feeRate * 100).toFixed(2) + '%');
    setText('vaPI', money.format(r.pay));
    setText('vaTaxMo', money.format(annualTax / 12));
    setText('vaInsMo', money.format(ins / 12));
    setText('vaHoaMo', money.format(hoa));
    setText('vaBase', money.format(base));
    setText('vaCashClose', money.format(downAmt + (financed ? 0 : fee)));
    setText('vaTotalInterest', money.format(r.totalInterest));
    setText('vaTotalPaid', money.format(loan + r.totalInterest));

    var note;
    if (exempt) note = 'No funding fee: you marked yourself as exempt. Your lender confirms this from your VA Certificate of Eligibility.';
    else {
      var band = downPct >= 10 - 1e-9 ? '10% or more' : downPct >= 5 - 1e-9 ? '5% to under 10%' : 'under 5%';
      note = 'Funding fee of ' + (feeRate * 100).toFixed(2) + '% for ' + (subsequent ? 'a later use of your VA loan benefit' : 'a first VA loan') +
        ' with ' + band + ' down (VA rates in effect for ' + FEE_YEAR_LABEL + ').' +
        (financed ? ' It is added to the loan, so you pay interest on it.' : ' It is due in cash at closing.');
      if (downPct < 5 - 1e-9) note += ' Putting 5% down would cut the fee to 1.5%.';
      else if (downPct < 10 - 1e-9) note += ' Putting 10% down would cut the fee to 1.25%.';
    }
    note += ' VA loans charge no monthly mortgage insurance.';
    setText('vaFeeNote', note);

    el('vaSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.principal) + '</td><td>' + money.format(row.interest) +
        '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('vaForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
